functions._alpStrToB64:
function _alpStrToB64(s) {
  var bytes = new TextEncoder().encode(s);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// GET /repos/.../contents/<path> → returns parsed JSON content + sha (or null
// if 404). Used to fetch the existing manifest before update, and to pick up
// the SHA needed to PUT an existing file.

functions._alpGitHubGet:
function _alpGitHubGet(pat, repo, branch, filePath) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
    "?ref=" + encodeURIComponent(branch);
  return fetch(url, {
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  }).then(function (r) {
    if (r.status === 404) return null;
    if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

// PUT /repos/.../contents/<path> — creates or updates a file. Pass existingSha
// from a prior GET to update; omit to create new.

functions._alpGitHubPut:
function _alpGitHubPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
  var body = {
    message: message,
    content: _alpStrToB64(contentStr),
    branch: branch,
  };
  if (existingSha) body.sha = existingSha;
  return fetch(url, {
    method: "PUT",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  }).then(function (r) {
    if (!r.ok) return r.text().then(function (t) { throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

// GET an existing encrypted blob from the repo and decrypt it. Returns the
// decrypted envelope object (with `sections.<key>` array intact), or null
// if the file doesn't exist on the repo yet. Used by the selective-push
// path so we can merge IDB edits into the remote state without clobbering
// rows the user didn't pick.

functions._alpFetchAndDecryptSection:
function _alpFetchAndDecryptSection(pat, repo, branch, sectionKey) {
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  return _alpGitHubGet(pat, repo, branch, sec.filename).then(function (existing) {
    if (!existing) return null; // file not in repo yet — caller treats as empty
    var contentB64 = (existing.content || "").replace(/\s/g, "");
    var raw = atob(contentB64);
    var blob = JSON.parse(raw);
    if (sec.confidential) {
      var cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
      if (!cipher) return Promise.reject(new Error("no library cipher set — Settings → Global → 📦 LIBRARY CIPHER"));
      return window._eliDecryptFromRepo(cipher, blob);
    }
    return blob; // plaintext envelope
  });
}
// Selective payload: keep remote rows for unpicked ids, replace remote rows
// with IDB versions for picked ids. Used by BD Templates so the user can
// check just the templates they edited and leave the others untouched.
//
// pickedIds: array of stable row ids (e.g. ["bd_doc_1776885212831"]).
// idField:   row property used as the merge key (default "id").

functions._alpBuildSelectivePayload:
function _alpBuildSelectivePayload(sectionKey, version, pickedIds, idField) {
  idField = idField || "id";
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  var pat = _alpGetPat(); var repo = _alpGetRepo(); var branch = _alpGetBranch();
  if (!pat) return Promise.reject(new Error("no GitHub PAT set"));
  // Fetch + decrypt remote, load IDB, merge.
  return Promise.all([
    _alpFetchAndDecryptSection(pat, repo, branch, sectionKey),
    loadFeatureData(sec.storeName),
  ]).then(function (results) {
    var remoteEnvelope = results[0];
    var idbRows = Array.isArray(results[1]) ? results[1] : [];
    var remoteRows = (remoteEnvelope && remoteEnvelope.sections && Array.isArray(remoteEnvelope.sections[sectionKey]))
      ? remoteEnvelope.sections[sectionKey]
      : [];
    var idbById = {}; idbRows.forEach(function (r) { if (r && r[idField]) idbById[r[idField]] = r; });
    var pickedSet = {}; pickedIds.forEach(function (id) { pickedSet[id] = true; });
    // Start with remote: replace picked ids with IDB versions, keep unpicked as-is.
    var merged = remoteRows.map(function (r) {
      var id = r && r[idField];
      if (id && pickedSet[id] && idbById[id]) return idbById[id];
      return r;
    });
    // Picked ids that are in IDB but not in remote → append (new template).
    var existingRemoteIds = {}; remoteRows.forEach(function (r) { if (r && r[idField]) existingRemoteIds[r[idField]] = true; });
    pickedIds.forEach(function (id) {
      if (!existingRemoteIds[id] && idbById[id]) merged.push(idbById[id]);
    });
    var envelope = {
      schemaVersion: 1,
      exportedAt: new Date().toISOString(),
      sectionVersions: {},
      sections: {},
    };
    envelope.sectionVersions[sectionKey] = version;
    envelope.sections[sectionKey] = merged;
    var plaintextSize = JSON.stringify(envelope).length;
    if (!sec.confidential) {
      var plainJson = JSON.stringify(envelope, null, 2);
      return {
        json: plainJson, byteSize: new TextEncoder().encode(plainJson).length,
        rowCount: merged.length, plaintextSize: plaintextSize, encrypted: false,
        kept: remoteRows.length - pickedIds.filter(function (id) { return existingRemoteIds[id]; }).length,
        replaced: pickedIds.filter(function (id) { return existingRemoteIds[id] && idbById[id]; }).length,
        added: pickedIds.filter(function (id) { return !existingRemoteIds[id] && idbById[id]; }).length,
      };
    }
    var cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
    return window._eliEncryptForRepo(cipher, envelope).then(function (encrypted) {
      var encJson = JSON.stringify(encrypted, null, 2);
      return {
        json: encJson, byteSize: new TextEncoder().encode(encJson).length,
        rowCount: merged.length, plaintextSize: plaintextSize, encrypted: true,
        kept: remoteRows.length - pickedIds.filter(function (id) { return existingRemoteIds[id]; }).length,
        replaced: pickedIds.filter(function (id) { return existingRemoteIds[id] && idbById[id]; }).length,
        added: pickedIds.filter(function (id) { return !existingRemoteIds[id] && idbById[id]; }).length,
      };
    });
  });
}
// Build the upload payload for a section. For confidential sections this
// AES-GCM-encrypts the envelope with the library cipher; for public sections
// it returns the plaintext envelope JSON ready to PUT as-is.

functions._alpBuildSectionPayload:
function _alpBuildSectionPayload(sectionKey, version) {
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  if (typeof loadFeatureData !== "function") return Promise.reject(new Error("loadFeatureData unavailable"));
  var cipher = "";
  if (sec.confidential) {
    cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
    if (!cipher) return Promise.reject(new Error("no library cipher set — Settings → Global → 📦 LIBRARY CIPHER"));
  }
  return loadFeatureData(sec.storeName).then(function (rows) {
    if (!Array.isArray(rows)) rows = [];
    var envelope = {
      schemaVersion: 1,
      exportedAt: new Date().toISOString(),
      sectionVersions: {},
      sections: {},
    };
    envelope.sectionVersions[sectionKey] = version;
    envelope.sections[sectionKey] = rows;
    var plaintextSize = JSON.stringify(envelope).length;
    if (!sec.confidential) {
      var plainJson = JSON.stringify(envelope, null, 2);
      return {
        json: plainJson,
        byteSize: new TextEncoder().encode(plainJson).length,
        rowCount: rows.length,
        plaintextSize: plaintextSize,
        encrypted: false,
      };
    }
    return window._eliEncryptForRepo(cipher, envelope).then(function (encrypted) {
      var encJson = JSON.stringify(encrypted, null, 2);
      return {
        json: encJson,
        byteSize: new TextEncoder().encode(encJson).length,
        rowCount: rows.length,
        plaintextSize: plaintextSize,
        encrypted: true,
      };
    });
  });
}

// Full publish flow for one section: encrypt → PUT blob → fetch+update+PUT
// manifest. Returns a result object for the UI log.
//
// `selectiveIds` (optional): when provided, takes the decrypt-merge-encrypt
// path — only those row ids are taken from IDB, the rest stay as their
// remote version. Used by BD Templates so the user can push a subset without
// clobbering rows they didn't edit.

functions._alpPushOne:
function _alpPushOne(sectionKey, version, commitNote, logEl, selectiveIds) {
  var pat = _alpGetPat(); if (!pat) return Promise.reject(new Error("no GitHub PAT — set it in this tool's settings"));
  var repo = _alpGetRepo(); var branch = _alpGetBranch();
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  var append = function (msg) {
    if (logEl) {
      logEl.innerHTML += '<div style="font-size:10px; color:#475569; margin-top:2px;">' + msg + '</div>';
      logEl.scrollTop = logEl.scrollHeight;
    }
  };
  var isSelective = Array.isArray(selectiveIds);
  var verb = isSelective
    ? (sec.confidential ? "Selective: fetching remote + decrypt-merge-encrypt" : "Selective: fetching remote + merge")
    : (sec.confidential ? "Encrypting" : "Building plaintext envelope");
  append("📦 [" + sec.label + "] " + verb + (isSelective ? " (" + selectiveIds.length + " picked)" : "") + "…");
  var payloadPromise = isSelective
    ? _alpBuildSelectivePayload(sectionKey, version, selectiveIds, "id")
    : _alpBuildSectionPayload(sectionKey, version);
  return payloadPromise.then(function (payload) {
    var sizeMsg = payload.encrypted
      ? "✓ Encrypted: " + payload.rowCount + " rows · " + (payload.plaintextSize / 1024).toFixed(1) + " KB plaintext → " + (payload.byteSize / 1024).toFixed(1) + " KB ciphertext"
      : "✓ Built: " + payload.rowCount + " rows · " + (payload.byteSize / 1024).toFixed(1) + " KB plaintext envelope";
    append(sizeMsg);
    if (isSelective) {
      append("  merge: " + (payload.kept || 0) + " kept from remote · " + (payload.replaced || 0) + " replaced from IDB · " + (payload.added || 0) + " new");
    }
    append("⬆️ Fetching existing " + sec.filename + " (for SHA)…");
    return _alpGitHubGet(pat, repo, branch, sec.filename).then(function (existing) {
      var sha = existing && existing.sha;
      append(sha ? "  found existing — sha " + sha.slice(0, 8) + "…" : "  not present — creating new");
      append("⬆️ Pushing " + sec.filename + "…");
      var msg = "Update " + sec.filename + " · v" + version + " · " + payload.rowCount + " rows" + (commitNote ? " · " + commitNote : "");
      return _alpGitHubPut(pat, repo, branch, sec.filename, payload.json, msg, sha).then(function () {
        append("✓ " + sec.filename + " pushed");
        append("⬆️ Updating manifest entry " + sec.manifestId + "…");
        return _alpGitHubGet(pat, repo, branch, "tools-manifest-v2.json").then(function (manifestRes) {
          if (!manifestRes) throw new Error("manifest not found in repo");
          var manifestStr = atob((manifestRes.content || "").replace(/\s/g, ""));
          var manifestJson = JSON.parse(manifestStr);
          var entry = (manifestJson.tools || []).find(function (t) { return t.id === sec.manifestId; });
          if (!entry) throw new Error("manifest has no entry for " + sec.manifestId + " — add it manually first");
          entry.version = version;
          entry.size = payload.byteSize;
          entry.changelog = "v" + version + " · " + payload.rowCount + " rows · pushed " + new Date().toISOString().slice(0, 19) + "Z" + (commitNote ? " · " + commitNote : "");
          manifestJson.lastUpdated = new Date().toISOString();
          var newManifest = JSON.stringify(manifestJson, null, 2);
          return _alpGitHubPut(pat, repo, branch, "tools-manifest-v2.json", newManifest,
            "Bump " + sec.manifestId + " to v" + version, manifestRes.sha).then(function () {
            append("✅ Manifest updated — " + sec.label + " v" + version + " is live");
            return { sectionKey: sectionKey, version: version, byteSize: payload.byteSize, rowCount: payload.rowCount };
          });
        });
      });
    });
  }).catch(function (err) {
    append('<span style="color:#dc2626; font-weight:700;">❌ ' + (err && err.message ? err.message : "unknown error") + '</span>');
    throw err;
  });
}

