    if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
    var loadPromise = window._alpIdbCache[sectionKey]
      ? Promise.resolve(window._alpIdbCache[sectionKey])
      : loadFeatureData(sec.storeName).then(function (rows) {
        window._alpIdbCache[sectionKey] = Array.isArray(rows) ? rows : [];
        return window._alpIdbCache[sectionKey];
      });
    return loadPromise.then(function (rows) {
      if (!rows.length) {
        subEl.innerHTML = '<span style="color:#94a3b8;">No rows in IDB for this section.</span>';
        return;
      }
      var rowsHtml = rows.map(function (r) {
        var id = r && r.id;
        if (!id) return '';
        var name = r.name || "(untitled)";
        var sizeKb = JSON.stringify(r).length / 1024;
        var sizeStr = sizeKb < 1024 ? sizeKb.toFixed(0) + " KB" : (sizeKb / 1024).toFixed(1) + " MB";
