          '<input type="checkbox" class="alp-sub-row" data-alp-sub-section="' + sectionKey + '" data-alp-sub-id="' + id + '" checked style="cursor:pointer; margin:0;">' +
          '<span style="font-weight:600; color:#0f172a; flex:1;">' + name.replace(/&/g, "&amp;").replace(/</g, "&lt;") + '</span>' +
          '<span style="font-size:9px; color:#94a3b8; font-family:monospace;">' + id + '</span>' +
          '<span style="font-size:9px; color:#64748b; min-width:55px; text-align:right;">' + sizeStr + '</span>' +
        '</label>';
      }).join("");
      subEl.innerHTML =
        '<div style="font-size:10px; color:#7c2d12; margin-bottom:6px;">' +
          '<b>Selective push</b> — only checked rows will be sent from your IDB. Unchecked rows keep their <i>current remote version</i>. Click ' +
          '<a href="#" data-alp-sub-all="' + sectionKey + '" style="color:#1565c0; cursor:pointer;">all</a> / ' +
          '<a href="#" data-alp-sub-none="' + sectionKey + '" style="color:#1565c0; cursor:pointer;">none</a>.' +
        '</div>' + rowsHtml;
